"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["25111"],{16493(e){e.exports=JSON.parse('{"id":"FIN-1235","slug":"gini-coefficient","term":"Gini Coefficient","also_known_as":[],"difficulty":"Advanced","definition":"The Gini coefficient is a measure of inequality in the distribution of income or wealth within a population, ranging from 0, meaning perfect equality, to 1, meaning one person has everything.","explanation":["The Gini coefficient, developed by Italian statistician Corrado Gini in the early twentieth century, is one of the most widely used measures of inequality.","It is based on the Lorenz curve, which plots the cumulative share of income received by the population, ordered from poorest to richest. In a perfectly equal society, the Lorenz curve would be a straight diagonal line. The Gini coefficient measures how far the actual curve falls below that line.","For example, a country with a Gini coefficient of 0.25 has relatively equal incomes, while one with a coefficient of 0.50 or higher has high inequality. It is sometimes expressed on a scale of 0 to 100.","The Gini coefficient is convenient for comparing countries and tracking change over time, but it has limitations. Very different distributions can produce the same Gini coefficient, and it is more sensitive to changes in the middle of the distribution than at the extremes. Results also depend on whether income is measured before or after taxes and benefits."],"note":"","total":1500,"prev":{"slug":"gift-tax","term":"Gift Tax"},"next":{"slug":"go-to-market-strategy","term":"Go-to-Market Strategy"}}')}}]);